import org.apache.jena.rdf.model.Model;
import org.apache.jena.rdf.model.ModelFactory;
import org.apache.jena.rdf.model.Property;
import org.apache.jena.rdf.model.Resource;
import org.apache.jena.rdf.model.Statement;
import org.apache.jena.rdf.model.StatementIterator;
import org.apache.jena.util.Printer;

public class RDFSExample {
    public static void main(String[] args) {
        // Create an empty model
        Model model = ModelFactory.createDefaultModel();

        // Define the classes
        Resource animal = model.createResource("http://example.org/animal");
        Resource mammal = model.createResource("http://example.org/mammal");
        Resource human = model.createResource("http://example.org/human");

        // Define the properties
        Property hijoDe = model.createProperty("http://example.org/hijoDe");
        Property hijoAdoptivoDe = model.createProperty("http://example.org/hijoAdoptivoDe");

        // Set the domains and ranges of the properties
        hijoDe.setDomain(animal);
        hijoDe.setRange(human);
        hijoAdoptivoDe.setDomain(animal);
        hijoAdoptivoDe.setRange(human);

        // Add instances of the classes
        Resource dog = model.createResource("http://example.org/dog");
        Resource cat = model.createResource("http://example.org/cat");
        Resource john = model.createResource("http://example.org/john");
        Resource jane = model.createResource("http://example.org/jane");

        // Set the relationships between the instances
        model.add(dog, hijoDe, john);
        model.add(cat, hijoDe, john);
        model.add(john, hijoAdoptivoDe, jane);

        // Print the model before applying RDFS inference
        System.out.println("Model before inference:");
        Printer.print(model);

        // Apply RDFS inference
        model = model.getRDFNode().asModel();

        // Remove unnecessary resources from the inferred model
        model.remove(model.listStatements().removeAll());

        // Print the model after applying RDFS inference
        System.out.println("Model after inference:");
        Printer.print(model);
    }
}
```

